BEGIN;
DO $$
DECLARE own text; applicant text:='registration-fixture-20261020'; rejected text:='registration-rejected-20261020'; p uuid; otherp uuid; t uuid; app uuid; rejectedapp uuid; m uuid; blocked boolean; state jsonb;
BEGIN
 SELECT s.auth_subject INTO own FROM public.st_members s JOIN public.st_member_roles r ON r.member_id=s.id WHERE r.role_code='owner' LIMIT 1;
 IF own IS NULL THEN RAISE EXCEPTION 'Missing owner'; END IF;
 INSERT INTO auth.users(project,sub,username,email_verified) SELECT project,applicant,'registration_fixture_20',true FROM auth.users WHERE sub=own;
 INSERT INTO auth.users(project,sub,username,email_verified) SELECT project,rejected,'registration_reject_20',true FROM auth.users WHERE sub=own;
 PERFORM set_config('request.jwt.claim.sub',own,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 p:=public.st_create_project('registration transaction test','');otherp:=public.st_create_project('registration other project','');t:=public.st_create_task(p,'private task','','translate');
 PERFORM set_config('request.jwt.claim.sub',applicant,true);
 IF public.st_membership_status()->>'state'<>'unsubmitted' THEN RAISE EXCEPTION 'New account status'; END IF;
 state:=public.st_apply_membership('注册测试昵称');
 IF state->>'state'<>'pending' THEN RAISE EXCEPTION 'Pending account became member'; END IF;
 PERFORM public.st_apply_membership('重复申请不覆盖');
 blocked:=false;BEGIN PERFORM public.st_board(NULL);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Pending board access';END IF;
 blocked:=false;BEGIN PERFORM public.st_task_detail(t);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Pending task access';END IF;
 blocked:=false;BEGIN PERFORM public.st_pending_members();EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Applicant can list applicants';END IF;
 blocked:=false;BEGIN PERFORM 1 FROM public.st_member_applications;EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Direct table access';END IF;
 PERFORM set_config('request.jwt.claim.sub',own,true);
 SELECT (x->>'id')::uuid INTO app FROM jsonb_array_elements(public.st_pending_members()) x WHERE x->>'username'='registration_fixture_20';
 IF app IS NULL THEN RAISE EXCEPTION 'Owner cannot see application';END IF;
 blocked:=false;BEGIN PERFORM public.st_decide_member(app,true,NULL,'contributor');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Approval without project';END IF;
 PERFORM set_config('request.jwt.claim.sub',applicant,true);
 blocked:=false;BEGIN PERFORM public.st_decide_member(app,true,p,'lead');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Self approval';END IF;
 PERFORM set_config('request.jwt.claim.sub',own,true);
 PERFORM public.st_decide_member(app,true,p,'contributor');
 blocked:=false;BEGIN PERFORM public.st_decide_member(app,true,p,'lead');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Duplicate approval';END IF;
 PERFORM set_config('request.jwt.claim.sub',applicant,true);
 state:=public.st_board(p);
 IF public.st_membership_status()->>'state'<>'active' OR (state->'me'->>'owner')::boolean OR (state->>'can_manage')::boolean OR (state->>'can_review')::boolean OR jsonb_array_length(state->'projects')<>1 THEN RAISE EXCEPTION 'Approved scope';END IF;
 blocked:=false;BEGIN PERFORM public.st_board(otherp);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Cross-project read';END IF;
 IF jsonb_array_length(public.st_board(p)->'tasks')<>1 THEN RAISE EXCEPTION 'Approved task read';END IF;
 PERFORM set_config('request.jwt.claim.sub',rejected,true);PERFORM public.st_apply_membership('拒绝测试');
 PERFORM set_config('request.jwt.claim.sub',own,true);
 SELECT (x->>'id')::uuid INTO rejectedapp FROM jsonb_array_elements(public.st_pending_members()) x WHERE x->>'username'='registration_reject_20';
 PERFORM public.st_decide_member(rejectedapp,false);
 PERFORM set_config('request.jwt.claim.sub',rejected,true);
 IF public.st_membership_status()->>'state'<>'rejected' THEN RAISE EXCEPTION 'Rejected scope';END IF;
 blocked:=false;BEGIN PERFORM public.st_board(NULL);EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Rejected board access';END IF;
 PERFORM public.st_apply_membership('拒绝后重复申请');
 IF public.st_membership_status()->>'state'<>'rejected' THEN RAISE EXCEPTION 'Rejection overwritten';END IF;
 PERFORM set_config('request.jwt.claim.sub','nonexistent-registration-user',true);
 blocked:=false;BEGIN PERFORM public.st_apply_membership('伪造身份');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Unregistered identity';END IF;
 EXECUTE 'RESET ROLE';
 IF EXISTS(SELECT 1 FROM public.st_members WHERE auth_subject=rejected) THEN RAISE EXCEPTION 'Rejected account became member'; END IF;
 IF (SELECT count(*) FROM public.st_member_applications WHERE auth_subject=applicant)<>1 THEN RAISE EXCEPTION 'Duplicate rows';END IF;
 IF has_function_privilege('anon','public.st_apply_membership(text)','EXECUTE') OR has_table_privilege('authenticated','public.st_member_applications','SELECT') THEN RAISE EXCEPTION 'Public grants';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.st_audit_events WHERE entity_table='st_member_applications' AND entity_id=app::text AND operation='UPDATE') THEN RAISE EXCEPTION 'Missing audit';END IF;
END; $$;
SELECT 'PASS: pending/rejected users cannot access business data; authenticated self-registration is idempotent; owner-only approval assigns only selected project/role; invalid and duplicate approval blocked; no direct/anonymous access; audit recorded. All fixtures rolled back.' AS registration_verification;
ROLLBACK;
